-- ============================================================
-- ATUALIZANDO DADOS DAS TABELAS (3 UPDATEs)
-- ============================================================

-- UPDATE 1: Dentista 5 entra de férias e fica indisponível
UPDATE T_DENTISTA
SET    DISPONIBILIDADE = 0
WHERE  ID_DENTISTA = 5;

-- UPDATE 2: Atendimento 10 é concluído (status realizado + observações)
UPDATE T_ATENDIMENTO
SET    STATUS      = 'realizado',
       OBSERVACOES = 'Procedimento concluído com sucesso.'
WHERE  ID_ATENDIMENTO = 10;

-- UPDATE 3: Paciente 3 atualiza telefone de contato
UPDATE T_PACIENTE
SET    TELEFONE = '11987654321'
WHERE  ID_PACIENTE = 3;

COMMIT;


-- ============================================================
