-- DELETE 1: Remove uma notificação obsoleta (id 3 - col->den)
DELETE FROM Envia          WHERE  T_NOTIFICACAO_ID_NOTIFICACAO = 3;
DELETE FROM T_NOTIFICACAO  WHERE  ID_NOTIFICACAO = 3;

-- DELETE 2: Remove um exame que não foi mais necessário (id 35)
DELETE FROM FK_EXAME_ATEND WHERE  T_EXAME_ID_EXAME = 35;
DELETE FROM T_EXAME        WHERE  ID_EXAME = 35;

-- DELETE 3: Remove uma anotação antiga (id 14)
DELETE FROM T_ANOTACAO     WHERE  ID_ANOTACAO = 14;

COMMIT;


-- ============================================================
-- RELATORIOS (5 SELECTs - cobertura da rubrica Sprint 4)
-- ============================================================

-- ------------------------------------------------------------
-- RELATORIO 1 - Classificacao de Dados (ORDER BY)
-- Top 10 dentistas com maior número de pacientes vinculados
-- ------------------------------------------------------------
SELECT D.NOME                         "Dentista",
       D.ESPECIALIDADE                "Especialidade",
       COUNT(P.ID_PACIENTE)           "Qtd Pacientes"
FROM   T_DENTISTA D
LEFT   JOIN T_PACIENTE P ON P.ID_DENTISTA = D.ID_DENTISTA
GROUP  BY D.NOME, D.ESPECIALIDADE
ORDER  BY COUNT(P.ID_PACIENTE) DESC, D.NOME
FETCH  FIRST 10 ROWS ONLY;


-- ------------------------------------------------------------
-- RELATORIO 2 - Funcao Numerica Simples
-- Idade média dos pacientes (arredondada) e total de pacientes
-- ------------------------------------------------------------
SELECT ROUND(AVG(MONTHS_BETWEEN(SYSDATE, DATA_NASC) / 12), 1) "Idade Média (anos)",
       COUNT(*)                                                "Total de Pacientes",
       MIN(TRUNC(MONTHS_BETWEEN(SYSDATE, DATA_NASC) / 12))     "Mais Novo",
       MAX(TRUNC(MONTHS_BETWEEN(SYSDATE, DATA_NASC) / 12))     "Mais Velho"
FROM   T_PACIENTE;


-- ------------------------------------------------------------
-- RELATORIO 3 - Funcao de Grupo
-- Quantidade de atendimentos por status, ordenada pelos mais frequentes
-- ------------------------------------------------------------
SELECT STATUS                "Status",
       COUNT(*)              "Quantidade",
       MIN(DATA)             "Primeiro Atendimento",
       MAX(DATA)             "Último Atendimento"
FROM   T_ATENDIMENTO
GROUP  BY STATUS
HAVING COUNT(*) > 0
ORDER  BY COUNT(*) DESC;


-- ------------------------------------------------------------
-- RELATORIO 4 - Sub-consulta
-- Dentistas com mais pacientes que a média geral
-- ------------------------------------------------------------
SELECT D.ID_DENTISTA          "ID",
       D.NOME                 "Dentista",
       (SELECT COUNT(*)
        FROM   T_PACIENTE P
        WHERE  P.ID_DENTISTA = D.ID_DENTISTA) "Qtd Pacientes"
FROM   T_DENTISTA D
WHERE  (SELECT COUNT(*)
        FROM   T_PACIENTE P
        WHERE  P.ID_DENTISTA = D.ID_DENTISTA)
     > (SELECT AVG(QTD)
        FROM   (SELECT COUNT(*) AS QTD
                FROM   T_PACIENTE
                GROUP  BY ID_DENTISTA))
ORDER  BY 3 DESC;


-- ------------------------------------------------------------
-- RELATORIO 5 - Juncao de Tabelas (JOIN)
-- Atendimentos detalhados: paciente + dentista + campanha
-- ------------------------------------------------------------
SELECT A.ID_ATENDIMENTO        "ID Atend.",
       TO_CHAR(A.DATA, 'DD/MM/YY') "Data",
       A.TIPO                  "Tipo",
       A.STATUS                "Status",
       P.NOME                  "Paciente",
       D.NOME                  "Dentista",
       D.ESPECIALIDADE         "Especialidade",
       C.NOME                  "Campanha"
FROM   T_ATENDIMENTO A
INNER  JOIN T_PACIENTE P ON A.T_PACIENTE_ID_PACIENTE = P.ID_PACIENTE
INNER  JOIN T_DENTISTA D ON A.T_DENTISTA_ID_DENTISTA = D.ID_DENTISTA
INNER  JOIN T_CAMPANHA C ON A.ID_CAMPANHA            = C.ID_CAMPANHA
ORDER  BY A.DATA DESC
FETCH  FIRST 20 ROWS ONLY;
